using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides a web search tool for the research agent.
/// Uses Bing search via the HTML page and parses snippets.
/// Replace the implementation with a real Search API (e.g., Bing Search API, Google Custom Search)
/// for production use.
/// </summary>
public sealed class WebSearchTool
{
    private readonly HttpClient _httpClient;

    public WebSearchTool(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [Description("Search the web for information on a query. Returns a list of result snippets.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query string")] string query,
        CancellationToken cancellationToken = default)
    {
        Console.ForegroundColor = ConsoleColor.DarkCyan;
        Console.WriteLine($"  🔍 Searching: \"{query}\"");
        Console.ResetColor();

        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";

            using var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.UserAgent.ParseAdd(
                "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

            using var response = await _httpClient.SendAsync(
                request, cancellationToken);
            response.EnsureSuccessStatusCode();

            var html = await response.Content.ReadAsStringAsync(cancellationToken);

            var snippets = ParseSnippets(html);
            if (snippets.Count == 0)
            {
                return $"No results found for \"{query}\".";
            }

            return JsonSerializer.Serialize(new { query, results = snippets });
        }
        catch (Exception ex)
        {
            return $"Search failed for \"{query}\": {ex.Message}";
        }
    }

    private static List<object> ParseSnippets(string html)
    {
        var results = new List<object>();
        var searchIndex = 0;

        // Parse DuckDuckGo HTML results by extracting result snippets
        while (results.Count < 5)
        {
            var snippetStart = html.IndexOf(
                "class=\"result__snippet\"", searchIndex, StringComparison.Ordinal);
            if (snippetStart < 0) break;

            var titleStart = html.LastIndexOf(
                "class=\"result__a\"", snippetStart, StringComparison.Ordinal);

            var title = "Untitled";
            if (titleStart >= 0)
            {
                var tagClose = html.IndexOf('>', titleStart);
                var tagEnd = html.IndexOf("</a>", tagClose, StringComparison.Ordinal);
                if (tagClose >= 0 && tagEnd >= 0)
                {
                    title = StripHtml(html[(tagClose + 1)..tagEnd]).Trim();
                }
            }

            var contentStart = html.IndexOf('>', snippetStart) + 1;
            var contentEnd = html.IndexOf("</", contentStart, StringComparison.Ordinal);
            if (contentStart <= 0 || contentEnd < 0)
            {
                searchIndex = snippetStart + 1;
                continue;
            }

            var snippet = StripHtml(html[contentStart..contentEnd]).Trim();
            if (!string.IsNullOrWhiteSpace(snippet))
            {
                results.Add(new { title, snippet });
            }

            searchIndex = contentEnd;
        }

        return results;
    }

    private static string StripHtml(string input) =>
        System.Text.RegularExpressions.Regex.Replace(input, "<[^>]+>", " ").Trim();
}

using System.ComponentModel;
using System.Text.Json;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides note-taking tools for the research agent to store
/// and retrieve findings during a research session.
/// </summary>
public sealed class NoteTool
{
    private readonly List<NoteEntry> _notes = [];

    [Description("Save a research note with a category tag. Use this to record important findings.")]
    public string SaveNote(
        [Description("Short category label, e.g. 'overview', 'history', 'statistics'")] string category,
        [Description("The note content to save")] string content)
    {
        var entry = new NoteEntry(category, content, DateTime.UtcNow);
        _notes.Add(entry);

        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  📝 Note saved [{category}]: {Truncate(content, 80)}");
        Console.ResetColor();

        return $"Note #{_notes.Count} saved under \"{category}\".";
    }

    [Description("Retrieve all saved research notes, optionally filtered by category.")]
    public string GetNotes(
        [Description("Optional category filter. Pass empty string for all notes.")] string category = "")
    {
        var filtered = string.IsNullOrWhiteSpace(category)
            ? _notes
            : _notes.Where(n =>
                n.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

        if (filtered.Count == 0)
        {
            return string.IsNullOrWhiteSpace(category)
                ? "No notes saved yet."
                : $"No notes found for category \"{category}\".";
        }

        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  📋 Retrieving {filtered.Count} note(s)");
        Console.ResetColor();

        return JsonSerializer.Serialize(filtered, new JsonSerializerOptions
        {
            WriteIndented = true,
        });
    }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : string.Concat(text.AsSpan(0, maxLength), "...");

    private sealed record NoteEntry(string Category, string Content, DateTime SavedAt);
}

