+            var titleStart = html.LastIndexOf(
+                "class=\"result__a\"", snippetStart, StringComparison.Ordinal);
+
+            var title = "Untitled";
+            if (titleStart >= 0)
+            {
+                var tagClose = html.IndexOf('>', titleStart);
+                var tagEnd = html.IndexOf("</a>", tagClose, StringComparison.Ordinal);
+                if (tagClose >= 0 && tagEnd >= 0)
+                {
+                    title = StripHtml(html[(tagClose + 1)..tagEnd]).Trim();
+                }
+            }
+
+            var contentStart = html.IndexOf('>', snippetStart) + 1;
+            var contentEnd = html.IndexOf("</", contentStart, StringComparison.Ordinal);
+            if (contentStart <= 0 || contentEnd < 0)
+            {
+                searchIndex = snippetStart + 1;
+                continue;
+            }
+
+            var snippet = StripHtml(html[contentStart..contentEnd]).Trim();
+            if (!string.IsNullOrWhiteSpace(snippet))
+            {
+                results.Add(new { title, snippet });
+            }
+
+            searchIndex = contentEnd;
+        }
+
+        return results;
+    }
+
+    private static string StripHtml(string input) =>
+        System.Text.RegularExpressions.Regex.Replace(input, "<[^>]+>", " ").Trim();
+}
