using System.ComponentModel;
using System.Text.Json;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides note-taking tools for the research agent to store
/// and retrieve findings during a research session.
/// </summary>
public sealed class NoteTool
{
    private readonly List<NoteEntry> _notes = [];

    [Description("Save a research note with a category tag. Use this to record important findings.")]
    public string SaveNote(
        [Description("Short category label, e.g. 'overview', 'history', 'statistics'")] string category,
        [Description("The note content to save")] string content)
    {
        var entry = new NoteEntry(category, content, DateTime.UtcNow);
        _notes.Add(entry);

        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  📝 Note saved [{category}]: {Truncate(content, 80)}");
        Console.ResetColor();

        return $"Note #{_notes.Count} saved under \"{category}\".";
    }

    [Description("Retrieve all saved research notes, optionally filtered by category.")]
    public string GetNotes(
        [Description("Optional category filter. Pass empty string for all notes.")] string category = "")
    {
        var filtered = string.IsNullOrWhiteSpace(category)
            ? _notes
            : _notes.Where(n =>
                n.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

        if (filtered.Count == 0)
        {
            return string.IsNullOrWhiteSpace(category)
                ? "No notes saved yet."
                : $"No notes found for category \"{category}\".";
        }

        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  📋 Retrieving {filtered.Count} note(s)");
        Console.ResetColor();

        return JsonSerializer.Serialize(filtered, new JsonSerializerOptions
        {
            WriteIndented = true,
        });
    }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : string.Concat(text.AsSpan(0, maxLength), "...");

    private sealed record NoteEntry(string Category, string Content, DateTime SavedAt);
}

