using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;
using ResearchAgent.Tools;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL")
    ?? "gpt-4o-mini-2024-07-18";

// Build the IChatClient via MEAI abstraction
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// Create tool instances
using var httpClient = new HttpClient { Timeout = TimeSpan.FromSeconds(15) };
var searchTool = new WebSearchTool(httpClient);
var noteTool = new NoteTool();

// Register tools using AIFunctionFactory
var tools = new AITool[]
{
    AIFunctionFactory.Create(searchTool.SearchWebAsync),
    AIFunctionFactory.Create(noteTool.SaveNote),
    AIFunctionFactory.Create(noteTool.GetNotes),
};

// Build the agent with the orchestration layer
var agent = new ChatClientAgent(chatClient, tools);

// Get the research topic from the user
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

// Prepare the conversation with a system prompt guiding the agent's behavior
var history = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a thorough research agent. Given a topic, you will:

        1. Search the web for information using the SearchWebAsync tool.
           Perform at least 3 searches from different angles to get broad coverage.
        2. After each search, save the key findings using the SaveNote tool
           with an appropriate category (e.g., "overview", "history", "applications").
        3. Once you have gathered enough information, use GetNotes to review
           all your collected findings.
        4. Finally, write a well-structured summary of your research with sections
           and cite the sources where applicable.

        Be systematic: search → note → search → note → ... → review → summarize.
        """),
    new(ChatRole.User, $"Please research the following topic: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 15,
};

Console.WriteLine();
Console.ForegroundColor = ConsoleColor.Green;
Console.WriteLine($"═══ Researching: {topic} ═══");
Console.ResetColor();
Console.WriteLine();

// Stream the agent's responses
await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine();
Console.WriteLine();
Console.ForegroundColor = ConsoleColor.Green;
Console.WriteLine("═══ Research complete ═══");
Console.ResetColor();

