{
    new(ChatRole.System, """
        You are a thorough research agent. Given a topic, you will:

        1. Search the web for information using the SearchWebAsync tool.
           Perform at least 3 searches from different angles to get broad coverage.
        2. After each search, save the key findings using the SaveNote tool
           with an appropriate category (e.g., "overview", "history", "applications").
        3. Once you have gathered enough information, use GetNotes to review
           all your collected findings.
        4. Finally, write a well-structured summary of your research with sections
           and cite the sources where applicable.

        Be systematic: search → note → search → note → ... → review → summarize.
        """),
    new(ChatRole.User, $"Research this topic: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 15,
};

Console.WriteLine($"\nResearching: {topic}\n");

// Stream the agent's responses
await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant)
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine();
Console.ForegroundColor = ConsoleColor.Green;
Console.WriteLine("═══ Research complete ═══");
Console.ResetColor();

